      h1,
      h2,
      h3,
      p {
        margin: 0;
      }

      h1 {
        font-size: clamp(2.6rem, 5vw, 5rem);
        line-height: 0.96;
        letter-spacing: -0.05em;
        max-width: 10ch;
        margin-top: 1rem;
      }

      .hero-text {
        max-width: 42ch;
        margin-top: 1rem;
        color: var(--muted);
        font-size: 1.05rem;
