        align-items: center;
        justify-content: center;
        gap: 0.5rem;
        min-height: 3rem;
        padding: 0.85rem 1.25rem;
        border-radius: 999px;
        border: 1px solid transparent;
        font: inherit;
        font-weight: 700;
        text-decoration: none;
        cursor: pointer;
        transition: transform 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
      }

      .btn-primary {
        background: var(--accent-strong);
        color: #fff;
      }

      .btn-secondary {
        background: transparent;
        border-color: var(--line);
        color: var(--text);
      }

      .btn:hover {
        transform: translateY(-1px);
      }

      .btn:focus-visible,
      a:focus-visible,
      button:focus-visible {
        outline: 3px solid #0f73c8;
        outline-offset: 3px;
      }

      .hero-stats {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 0.75rem;
        margin-top: 1.75rem;
      }

      .stat {
        padding: 1rem;
        border-radius: var(--radius-md);
        background: var(--surface-alt);
        border: 1px solid #e7dfd1;
      }

      .stat strong {
        display: block;
        font-size: 1.2rem;
        margin-bottom: 0.2rem;
      }

      .hero-visual {
        position: relative;
        overflow: hidden;
        min-height: 420px;
        padding: 1.2rem;
        background:
          linear-gradient(180deg, rgba(255,255,255,0.5), rgba(255,255,255,0.15)),
          linear-gradient(145deg, #e7efe8 0%, #f9ece0 45%, #fff 100%);
      }

      .visual-panel {
        position: absolute;
        inset: 1.25rem;
        border-radius: calc(var(--radius-xl) - 6px);
        border: 1px solid rgba(24, 23, 22, 0.08);
        overflow: hidden;
      }

      .visual-panel::before,
      .visual-panel::after {
        content: "";
        position: absolute;
        border-radius: 999px;
        background: linear-gradient(135deg, rgba(31, 95, 74, 0.18), rgba(185, 107, 58, 0.18));
      }

      .visual-panel::before {
        width: 18rem;
        height: 18rem;
        left: -3rem;
        top: -1rem;
      }

      .visual-panel::after {
        width: 13rem;
        height: 13rem;
        right: -1rem;
        bottom: -2rem;
      }

      .product-stage {
        position: absolute;
        left: 50%;
        top: 54%;
        transform: translate(-50%, -50%);
        width: min(76%, 380px);
        aspect-ratio: 1;
        border-radius: 2rem;
        background: linear-gradient(180deg, rgba(255,255,255,0.82), rgba(255,255,255,0.45));
        box-shadow: inset 0 1px 0 rgba(255,255,255,0.75);
        display: grid;
        place-items: center;
      }

      .product-stage svg {
        width: 76%;
        height: auto;
      }

      .floating-chip {
        position: absolute;
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        padding: 0.65rem 0.85rem;
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.88);
        border: 1px solid rgba(24, 23, 22, 0.08);
        box-shadow: 0 10px 20px rgba(24, 23, 22, 0.08);
        font-weight: 700;
      }

      .chip-top {
        top: 1.2rem;
        left: 1.2rem;
      }

      .chip-bottom {
        right: 1.2rem;
        bottom: 1.2rem;
      }

      .dot {
        width: 0.7rem;
        height: 0.7rem;
        border-radius: 999px;
        background: var(--warm);
      }

      main {
        margin-top: 1.5rem;
      }

      .section-card {
        padding: 1.35rem;
        margin-top: 1.25rem;
      }

      .section-head {
        display: flex;
        justify-content: space-between;
        align-items: end;
        gap: 1rem;
        margin-bottom: 1rem;
      }

      .section-head p {
        color: var(--muted);
        max-width: 52ch;
      }

      .section-link {
        white-space: nowrap;
        font-weight: 700;
        color: var(--accent-strong);
      }

      .product-grid,
      .deal-grid,
      .editorial-grid {
        display: grid;
        gap: 1rem;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .deal-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .editorial-grid {
        grid-template-columns: 1.2fr 1fr 1fr;
      }

      .product-card {
        overflow: hidden;
        display: flex;
        flex-direction: column;
        min-width: 0;
      }

      .product-art {
        min-height: 180px;
        padding: 1rem;
        background: linear-gradient(180deg, #f3eee4 0%, #ffffff 100%);
        border-bottom: 1px solid var(--line);
        display: grid;
        place-items: center;
      }

      .product-art svg {
        width: 100%;
        max-width: 210px;
        height: auto;
      }

      .product-body {
        padding: 1rem 1rem 1.15rem;
        display: grid;
        gap: 0.55rem;
      }

      .product-meta {
        display: flex;
        justify-content: space-between;
        gap: 0.75rem;
        align-items: start;
      }

      .product-meta strong {
        display: block;
        font-size: 1rem;
      }

      .product-meta span {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .price {
        font-weight: 800;
        color: var(--accent-strong);
        white-space: nowrap;
      }

      .product-body p {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .chip-row {
        display: flex;
        flex-wrap: wrap;
        gap: 0.45rem;
      }

      .chip {
        display: inline-flex;
        align-items: center;
        min-height: 2rem;
        padding: 0.3rem 0.7rem;
        border-radius: 999px;
        background: var(--surface-alt);
        border: 1px solid var(--line);
        font-size: 0.82rem;
        font-weight: 700;
        color: var(--muted);
      }

      .deal-card,
      .content-card {
        padding: 1.2rem;
        min-width: 0;
      }

      .deal-card {
        background:
          linear-gradient(180deg, rgba(255,255,255,0.15), rgba(255,255,255,0.9)),
          linear-gradient(135deg, #e7f0ea 0%, #f8ece1 100%);
      }

      .deal-card strong,
      .content-card strong {
        display: block;
        font-size: 1.15rem;
        margin-bottom: 0.5rem;
      }

      .deal-card p,
      .content-card p {
        color: var(--muted);
      }

      .deal-cta {
        display: inline-flex;
        margin-top: 1rem;
        font-weight: 700;
        color: var(--accent-strong);
      }

      .content-card {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        min-height: 280px;
      }

      .content-card .article-kicker {
        color: var(--warm);
        font-size: 0.84rem;
        font-weight: 800;
        letter-spacing: 0.05em;
        text-transform: uppercase;
      }

      .content-image {
        border-radius: var(--radius-md);
        overflow: hidden;
        margin-top: 1rem;
        border: 1px solid var(--line);
        min-height: 132px;
        background: linear-gradient(135deg, #dce8e2 0%, #f2e6d8 100%);
      }

      .content-image svg {
        width: 100%;
        height: auto;
      }

      footer {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        margin-top: 1.5rem;
        padding: 1rem 0 0;
        color: var(--muted);
        flex-wrap: wrap;
      }

      .footer-links {
        display: flex;
        gap: 1rem;
        flex-wrap: wrap;
      }

      .footer-links a {
        font-weight: 700;
      }

      @media (max-width: 980px) {
        .hero,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .product-grid,
        .deal-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }

      @media (max-width: 720px) {
        header {
          position: static;
        }

        .topbar {
          border-radius: var(--radius-lg);
          align-items: start;
          flex-direction: column;
        }

        nav ul {
          justify-content: flex-start;
        }

        .hero-copy,
        .hero-visual {
          min-height: auto;
        }

        .hero-copy {
          padding: 1.4rem;
        }

        h1 {
          max-width: none;
        }

        .hero-stats,
        .product-grid,
        .deal-grid {
          grid-template-columns: 1fr;
        }

        .section-head {
          align-items: start;
          flex-direction: column;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-alt: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --line: ButtonBorder;
          --accent: ButtonText;
          --accent-strong: ButtonText;
          --accent-soft: Canvas;
          --warm: ButtonText;
          --shadow: none;
        }

        .skip-link,
        .btn-primary,
        .brand-mark,
        .eyebrow {
          forced-color-adjust: auto;
        }

        .btn,
        .topbar,
        .hero-copy,
        .hero-visual,
        .section-card,
        .deal-card,
        .content-card,
        .product-card,
        .stat {
          border-color: ButtonBorder;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const featuredProducts = [
