      const icon = (name) => {
        const icons = {
          bag: '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="M14 18h20l2 22H12l2-22Z" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/><path d="M18 18c0-3.3 2.2-6 6-6s6 2.7 6 6" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><circle cx="18" cy="28" r="2" fill="currentColor"/><circle cx="30" cy="28" r="2" fill="currentColor"/></svg>',
