            <a class="section-link" href="#deals" aria-label="Shop ${item.name}">Shop now</a>
          </div>
        </article>
      `;

      const dealCard = (item) => `
        <article class="deal-card">
          <strong>${item.title}</strong>
          <p>${item.copy}</p>
          <a class="deal-cta" href="#featured">${item.cta}</a>
        </article>
      `;

      const storyCard = (item, index) => `
        <article class="content-card">
          <div>
            <span class="article-kicker">${item.kicker}</span>
            <strong>${item.title}</strong>
            <p>${item.copy}</p>
          </div>
          <div class="content-image" aria-hidden="true">
            ${
              index === 0
                ? '<svg viewBox="0 0 420 180" fill="none"><rect width="420" height="180" rx="20" fill="#f7f1e8"/><path d="M25 135c38-40 92-54 163-43 39 6 77 20 115 42" stroke="#1f5f4a" stroke-width="14" stroke-linecap="round"/><path d="M294 50c26 4 47 16 64 36" stroke="#b96b3a" stroke-width="12" stroke-linecap="round"/><circle cx="324" cy="62" r="24" fill="#dce8e2"/></svg>'
                : index === 1
                ? '<svg viewBox="0 0 420 180" fill="none"><rect width="420" height="180" rx="20" fill="#f4ede3"/><rect x="50" y="32" width="320" height="116" rx="18" fill="#ffffff"/><path d="M88 110h244" stroke="#1f5f4a" stroke-width="12" stroke-linecap="round"/><path d="M118 72h180" stroke="#b96b3a" stroke-width="12" stroke-linecap="round"/><circle cx="324" cy="56" r="18" fill="#dce8e2"/></svg>'
                : '<svg viewBox="0 0 420 180" fill="none"><rect width="420" height="180" rx="20" fill="#e8efe8"/><path d="M70 138h280" stroke="#1f5f4a" stroke-width="12" stroke-linecap="round"/><path d="M132 54h156v74H132z" fill="#ffffff"/><path d="M156 54v74M264 54v74" stroke="#b96b3a" stroke-width="10"/></svg>'
            }
          </div>
        </article>
      `;

      document.getElementById("app").innerHTML = `
        <div class="page-shell">
          <header>
            <div class="topbar">
              <a class="brand" href="#main-content">
                <span class="brand-mark">${icon("bag")}</span>
                <span>Atelier Retail</span>
              </a>
              <nav aria-label="Primary navigation">
                <ul>
                  <li><a href="#featured">Featured products</a></li>
                  <li><a href="#deals">Deals</a></li>
                  <li><a href="#stories">Editorial</a></li>
                </ul>
              </nav>
            </div>
          </header>

          <main id="main-content">
            <section class="hero" aria-labelledby="home-title">
