                  <div class="hero-stats" aria-label="Store highlights">
                    <div class="stat">
                      <strong>120+</strong>
                      New arrivals
                    </div>
                    <div class="stat">
                      <strong>4.8/5</strong>
                      Customer rating
                    </div>
                    <div class="stat">
                      <strong>Free</strong>
                      Shipping over $100
                    </div>
                  </div>
                </div>
              </div>

              <div class="hero-visual" aria-label="Featured product showcase">
                <div class="visual-panel" aria-hidden="true"></div>
                <div class="floating-chip chip-top"><span class="dot"></span> Limited release</div>
                <div class="floating-chip chip-bottom"><span class="dot"></span> Weekend drop</div>
                <div class="product-stage" aria-hidden="true">
                  ${productArt("jacket")}
                </div>
              </div>
            </section>

            <section class="section-card" id="featured" aria-labelledby="featured-title">
